import React from "react";
import SinglePost from "./singelPostComponent";

class Home extends React.Component {

constructor(props){
    super(props);

    this.state = {
        posts: [],
        loading: true,
        base_URL: '',
        page: 1,
        hasMore: true
    };
}


    componentDidMount() {
        console.log("Home Mounted");

        fetch("http://localhost:8000/api/")
            .then(res => res.json())
            .then(json => {
                this.setState({
                    loading: false,
                    posts: json.posts.data,
                    base_URL: json.base_URL
                });
                console.log(this.state.posts);
            })
            .catch(err => {
                console.log("ERR:", err);
                this.setState({ loading: false });
            });
    }

    render() {

        if (this.state.loading) {
            return <p>Loading...</p>;
        }

        return (
            <main className="container mt-4 pt-5">
                <div className="container-fluid mt-5">
                    {this.state.posts.map(post => (
                        <SinglePost
                            id={post.id}
                            title={post.title}
                            text={post.text}
                            img={post.img}
                            base_URL={this.state.base_URL}
                            user_img={post.user.img}
                            name={post.user.family}
                            is_like= {post.is_like}

                            count_like={post.count_like}
                            count_comment={post.count_comment}
                            display_time={post.display_time}
                        />
                    ))}
                </div>
            </main>
        );
    }
}

export default Home;
